import { isDeepStrictEqual } from "node:util";
import { Agent, computerTool } from "@openai/agents";
import {
  createRetainedAgentRunner,
  RetainedResponseNotAdmitted,
} from "@katalon-experiments/ai-client/agents";
import { requestProvider } from "./provider.mjs";

function readSteps(body) {
  const messages = body.output?.filter((item) => item.type === "message");
  if (
    body.output?.some((item) => !["message", "reasoning"].includes(item.type))
  )
    return null;
  const text =
    messages?.map(
      (message) =>
        message.content
          ?.filter((part) => part.type === "output_text")
          .map((part) => part.text) ?? [],
    ) ?? [];
  const parse = (value) => {
    try {
      const { steps } = JSON.parse(value);
      return Array.isArray(steps)
        ? steps.filter((step) => typeof step === "string" && step.trim())
        : [];
    } catch {
      return [];
    }
  };
  // Transport boundaries need not match document boundaries. Read complete
  // objects in order from the joined stream, respecting braces inside strings.
  const joined = text.flat().join("");
  const documents = [];
  const add = (value, start, end) => {
    const steps = parse(value);
    if (steps.length) documents.push({ start, end, steps });
  };
  let start = -1;
  let depth = 0;
  let quoted = false;
  let escaped = false;
  for (let i = 0; i < joined.length; i++) {
    const character = joined[i];
    if (start < 0) {
      if (character === "{") {
        start = i;
        depth = 1;
      }
      continue;
    }
    if (quoted) {
      if (escaped) escaped = false;
      else if (character === "\\") escaped = true;
      else if (character === '"') quoted = false;
    } else if (character === '"') quoted = true;
    else if (character === "{") depth++;
    else if (character === "}" && --depth === 0) {
      add(joined.slice(start, i + 1), start, i + 1);
      start = -1;
    }
  }
  // An unfinished neighboring document must not swallow a complete message or
  // text part. Source ranges keep overlapping representations from duplicating
  // observations that the joined stream already recovered.
  let offset = 0;
  for (const parts of text) {
    const message = parts.join("");
    add(message, offset, offset + message.length);
    for (const part of parts) {
      add(part, offset, offset + part.length);
      offset += part.length;
    }
  }
  documents.sort((a, b) => a.start - b.start || b.end - a.end);
  const steps = [];
  let end = -1;
  for (const document of documents) {
    if (document.start < end) continue;
    steps.push(...document.steps);
    end = document.end;
  }
  return steps.length ? steps : null;
}

export async function requestBrowserRecap(options) {
  const { request, signal } = options;
  const closed = () => {
    throw new Error("Recap cannot perform actions");
  };
  const agent = new Agent({
    name: "Runner",
    tools: request.tools.map(() =>
      computerTool({
        computer: {
          screenshot: closed,
          click: closed,
          doubleClick: closed,
          drag: closed,
          keypress: closed,
          move: closed,
          scroll: closed,
          type: closed,
          wait: closed,
        },
      }),
    ),
    modelSettings: {
      reasoning: request.reasoning,
      maxTokens: request.max_output_tokens,
      ...(request.tool_choice ? { toolChoice: request.tool_choice } : {}),
    },
    outputType: request.text.format,
  });
  let steps;
  const runner = createRetainedAgentRunner({
    model: request.model,
    store: request.store,
    async dispatch(wire) {
      if (
        !isDeepStrictEqual(JSON.parse(JSON.stringify(wire)), {
          ...request,
          include: [],
          stream: false,
        })
      )
        throw new Error("Runner recap request changed during SDK conversion");
      // The host sends the original bytes and records the original reply.
      const { response, body } = await requestProvider(options);
      if (response.ok && body?.status === "completed" && !signal?.aborted)
        steps = readSteps(body);
      if (!steps)
        throw new RetainedResponseNotAdmitted("Invalid browser recap");
      return {
        ...body,
        output: [
          {
            type: "message",
            role: "assistant",
            status: "completed",
            content: [{ type: "output_text", text: JSON.stringify({ steps }) }],
          },
        ],
      };
    },
  });
  try {
    await runner.run(
      agent,
      request.input.map((item) => ({
        type: "unknown",
        providerData: item,
      })),
      { previousResponseId: request.previous_response_id, maxTurns: 1 },
    );
  } catch (error) {
    // Older replies can omit model identity. Only the host can publish its
    // validated recap. Tool selection is disabled; no subsequent turn executes.
    if (!(error instanceof RetainedResponseNotAdmitted)) throw error;
  }
  return steps ?? null;
}
